<script module lang="ts">
/**
 * Browsable view of an arbitrary JSON value (`design/components/json-tree.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/json-tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  agentMember,
  joinSlot,
  jsonTreeBranches,
  jsonTreeExpanded,
  setJsonTreeBranch,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/json-tree.module.css'
import JsonTreeEntry from './JsonTreeEntry.svelte'

export interface JsonTreeProps {
  /**
   * Any JSON value; `undefined` and other non-JSON values render as their `String()` form rather
   * than crashing a page that already has a bug.
   */
  data: unknown
  /**
   * Levels open at mount (`0` all closed, `Infinity` for payloads known to be small);
   * uncontrolled afterwards, because browsing is not app state.
   */
  defaultDepth?: number
  /**
   * The tree's accessible name, such as "Response body" rather than "JSON".
   */
  label: string
}
</script>

<script lang="ts">
let { data, defaultDepth = 1, label: labelOwn }: JsonTreeProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let tree = $state<HTMLElement | null>(null)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'JsonTree',
    element: () => tree,
    state: () => ({
      expanded: jsonTreeExpanded(tree, styles.toggle, styles.key),
      branches: jsonTreeBranches(tree, styles.toggle, styles.key),
    }),
    actions: {
      expand: {
        argument: 'id',
        run: (value) => setJsonTreeBranch(tree, styles.toggle, styles.key, value, true),
      },
      collapse: {
        argument: 'id',
        run: (value) => setJsonTreeBranch(tree, styles.toggle, styles.key, value, false),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<ul bind:this={tree} class={styles.root} aria-label={label} data-member="json-tree"
    ><JsonTreeEntry value={data} depth={0} {defaultDepth}
  /></ul
>{/if
}{@render joined.end?.()}
